from boltons.setutils import IndexedSet, _MISSING

def check_invariants(s, ctx):
    items, ded, iim = s.item_list, s.dead_indices, s.item_index_map
    missing = {i for i, v in enumerate(items) if v is _MISSING}
    covered = set()
    prev = None
    for d_start, d_stop in ded:
        assert 0 <= d_start < d_stop <= len(items), f"{ctx}: range {(d_start,d_stop)} len={len(items)}"
        if prev is not None:
            assert d_start > prev, f"{ctx}: adjacency/disorder {prev} then {d_start}"
        covered.update(range(d_start, d_stop))
        prev = d_stop
    assert covered == missing, f"{ctx}: coverage {sorted(covered)} vs missing {sorted(missing)}"
    assert len(iim) == len(s)
    assert sorted(iim.values()) == sorted(i for i, v in enumerate(items) if v is not _MISSING)
    for item, pos in iim.items():
        assert items[pos] is item, f"{ctx}: iim slot"
    for a in range(len(s)):
        r = s._get_real_index(a)
        assert 0 <= r < len(items) and items[r] is not _MISSING, f"{ctx}: real_index({a})={r}"

def check_all(s, model, ctx, do_slices):
    assert list(s) == model, f"{ctx}: iter {list(s)} != {model}"
    assert len(s) == len(model)
    n = len(model)
    for i in range(-n - 3, n + 3):
        try: got, gi = s[i], 'ok'
        except IndexError: gi = 'err'
        if -n <= i < n: exp, ei = model[i if i >= 0 else n + i], 'ok'
        else: exp, ei = None, 'err'
        assert gi == ei and (gi == 'err' or got == exp), f"{ctx}: s[{i}] {gi}:{got!r} vs {ei}:{exp!r}"
    if do_slices:
        fresh = IndexedSet(model)
        small = list(range(-n - 2, n + 2)) + [None]
        for a in small:
            for b in small:
                for step in (None, 1, 2, 3, 5, -1, -2):
                    got = list(s[a:b:step])
                    if step is None or step > 0:
                        exp = model[a:b:step]
                    else:
                        exp = list(reversed(model))[a:b:abs(step)]
                    fg = list(fresh[a:b:step])
                    assert got == exp, f"{ctx}: s[{a}:{b}:{step}] {got!r} vs model {exp!r}"
                    assert got == fg, f"{ctx}: s[{a}:{b}:{step}] {got!r} vs fresh {fg!r}"
    for v in model:
        assert s.index(v) == model.index(v), f"{ctx}: index({v})"
    # pop trial
    for i in list(range(-n - 3, n + 3)) + [None]:
        s2, m2 = IndexedSet(s), list(model)
        try: g = ('ok', s2.pop(i))
        except IndexError: g = ('err',)
        try: e = ('ok', m2.pop() if i is None else m2.pop(i))
        except IndexError: e = ('err',)
        assert g == e, f"{ctx}: pop({i}) {g} vs {e}"
        assert list(s2) == m2, f"{ctx}: after pop({i}) {list(s2)} vs {m2}"
        check_invariants(s2, f"{ctx} after pop({i})")

seed = int(sys.argv[1]); trials = int(sys.argv[2]); do_slices_every = int(sys.argv[3])
random.seed(seed)
fails = 0
t0 = time.time()
for trial in range(trials):
    n = random.choice([1, 2, 3, 5, 8, 16, 32, 64, 100, 200])
    s = IndexedSet(range(n)); model = list(range(n))
    mode = random.choice(['tail', 'front', 'mid', 'random'])
