            else: idx = random.randrange(len(model))
            v = model[idx]; s.remove(v); model.pop(idx); ops.append(f'remove({v})')
        elif op == 'pop':
            i = random.choice([None, -1, 0, len(model)-1, random.randrange(len(model)),
                               -len(model), -len(model)-1, len(model), len(model)+5, -len(model)-5])
