from boltons.setutils import IndexedSet, _MISSING
import random

random.seed(99)
fails = []

def exp_slice(model, a, b, c):
    n = len(model)
    if c is not None and c < 0:
        seq = list(reversed(model))
        if a is not None and a < 0: a = max(n + a, 0)
        if b is not None and b < 0: b = max(n + b, 0)
        return seq[a:b:-c]
    return model[a:b:c]

def check(s, model, ctx):
    di = s.dead_indices
    missing = {i for i, v in enumerate(s.item_list) if v is _MISSING}
    covered = set()
    for a, b in di:
        if not (0 <= a < b <= len(s.item_list)):
            fails.append(('dedrange', ctx, list(di), len(s.item_list))); return
        covered |= set(range(a, b))
    if covered != missing:
        fails.append(('dedcover', ctx, list(di), sorted(missing))); return
    for i in range(len(di) - 1):
        if di[i][1] >= di[i+1][0]:
            fails.append(('dedorder', ctx, list(di))); return
    for item, pos in s.item_index_map.items():
        if s.item_list[pos] is not item:
            fails.append(('map', ctx, item, pos)); return
    if list(s) != model or len(s) != len(model):
        fails.append(('iter', ctx, list(s), model)); return
    n = len(model)
    for i in range(-n - 2, n + 2):
        exp = model[i] if -n <= i < n else 'RAISE'
        try: got = s[i]
