                        except IndexError: continue
                        fail(f'pop({i}) raised but list allows', seed)
                        continue
                    try:
                        exp = ref.pop(i)
                    except IndexError:
                        fail(f'pop({i}) returned {got} but list raises, ref={ref}', seed)
                        continue
                    if got != exp: fail(f'pop({i}) got {got} exp {exp} ref={ref}', seed)
                else:
