# Brute-force: simulate the new round-robin loop and compare outputs
# against builtin zip for many length combinations, strict on/off.
import itertools

def simulate(lens, strict):
    iters = [iter(range(n)) for n in lens]
    count = len(iters)
    out = []
    pulls = [0]*count
    while True:
        values = [None]*count
        exhausted = set()
        for j, it in enumerate(iters):
            pulls[j] += 1
            try:
                values[j] = next(it)
            except StopIteration:
                exhausted.add(j)
