    // (e.g. 0.0.2-1 -> 1.0.0, 1.0.0-1 -> 2.0.0): only a major bump can
    // publish that stable release after such a prerelease.
    return 'major'
  }

  // add the `pre` prefix if we are going to a prerelease version
  const prefix = highHasPre ? 'pre' : ''

  if (v1.major !== v2.major) {
